Set-StrictMode -Version Latest
function Get-Value($r,[string[]]$names){foreach($n in $names){$p=$r.PSObject.Properties|?{$_.Name -replace '[^a-z0-9]','' -ieq ($n -replace '[^a-z0-9]','')};if($p -and [string]$p.Value -and [string]$p.Value -notin @('-','None','null')){return [string]$p.Value}};return ''}
function Get-Cves([string]$text){if(!$text){return @()};return @([regex]::Matches($text,'CVE-\d{4}-\d{4,}', 'IgnoreCase')|% Value|% ToUpper|sort -Unique)}
function Convert-Rows($rows,[string]$source){$out=@();foreach($r in $rows){$blob=($r.PSObject.Properties|% Value)-join ' ';$c=Get-Cves $blob;$title=Get-Value $r @('Name','Title','Finding','Plugin Name','CVE ID');if(!$title){$title=if($c){$c[0]}else{'Finding'}};$risk=Get-Value $r @('Severity','Risk','Risk Factor','Priority');$out+=[pscustomobject]@{source=$source;cves=$c;title=$title;severity=$risk;cvss=Get-Value $r @('CVSS Score','CVSS','CVSS v3.0 Base Score','Base Score','Score');host=Get-Value $r @('Hostname','Host','Device','Asset','IP Address');product=Get-Value $r @('Product','Plugin Family','Category','Type');description=Get-Value $r @('Description','Synopsis','Analysis','Details','Summary');fix=Get-Value $r @('Remediation','Solution','Recommended Action','Workflow','Fix','Guidance');status=Get-Value $r @('Status','State','Resolution');raw=$r}};return $out}
function Parse-CrowdStrike([string]$Path){return Convert-Rows (Import-Csv $Path) 'crowdstrike'}
function Parse-Nessus([string]$Path){return Convert-Rows (Import-Csv $Path) 'nessus'}
function Parse-Blumira([string]$Path){return Convert-Rows (Import-Csv $Path) 'blumira'}
